            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x233F8089514C8E67ULL) + aOUSaltE[(((511U - aIndex) + 301U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x5B28AC95886C2D45ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4F3F0906954F11E7ULL), 53U);
